ALTER TABLE src_crm.crm_opportunity ADD COLUMN source_lead_no VARCHAR(32) NULL,ADD COLUMN contact_name VARCHAR(50) NULL,ADD COLUMN probability DECIMAL(5,2) NOT NULL DEFAULT 10,ADD COLUMN expected_close_date DATE NULL,ADD COLUMN lost_reason VARCHAR(300) NULL;
CREATE TABLE IF NOT EXISTS src_crm.crm_opportunity_product(id BIGINT AUTO_INCREMENT PRIMARY KEY,opportunity_no VARCHAR(32) NOT NULL,product_code VARCHAR(32) NOT NULL,product_name VARCHAR(200),expected_qty DECIMAL(18,4) NOT NULL,unit_code VARCHAR(16),expected_price DECIMAL(18,4),KEY idx_opp_product(opportunity_no));
CREATE TABLE IF NOT EXISTS src_crm.crm_competitor(id BIGINT AUTO_INCREMENT PRIMARY KEY,opportunity_no VARCHAR(32) NOT NULL,competitor_name VARCHAR(200) NOT NULL,quoted_amount DECIMAL(18,2),strengths VARCHAR(500),weaknesses VARCHAR(500),KEY idx_competitor_opp(opportunity_no));
CREATE TABLE IF NOT EXISTS src_crm.crm_sales_forecast(id BIGINT AUTO_INCREMENT PRIMARY KEY,forecast_month CHAR(7) NOT NULL,owner_user VARCHAR(32),dept_code VARCHAR(32),product_code VARCHAR(32),forecast_amount DECIMAL(18,2) NOT NULL,weighted_amount DECIMAL(18,2) NOT NULL,generated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),KEY idx_forecast_month(forecast_month));
